// Independent readers over generated bytes, checking that families are valid
// instances of their format subset and that Truth matches the bytes.

func gather(t *testing.T, pat string) map[string][]collectedMember {
	t.Helper()
	cfg := smallCfg()
	cfg.Families = []string{pat}
	var c collect
	if _, err := Generate(cfg, &c); err != nil {
		t.Fatal(err)
	}
	out := map[string][]collectedMember{}
	for _, m := range c.m {
		out[m.Family] = append(out[m.Family], collectedMember{m, c.data[m.Path]})
	}
	return out
}

type collectedMember struct {
	Member
	data []byte
}

func readZip(t *testing.T, b []byte) (names []string, content map[string][]byte, methods map[string]uint16) {
	t.Helper()
	zr, err := zip.NewReader(bytes.NewReader(b), int64(len(b)))
	if err != nil {
		t.Fatal(err)
	}
	content, methods = map[string][]byte{}, map[string]uint16{}
	for _, f := range zr.File {
		rc, err := f.Open()
		if err != nil {
			t.Fatal(err)
		}
		d, err := io.ReadAll(rc)
		if err != nil {
			t.Fatalf("%s: %v (crc or inflate failure)", f.Name, err)
		}
		names = append(names, f.Name)
		content[f.Name] = d
		methods[f.Name] = f.Method
	}
	return
}

func TestZipFamiliesValidAndTruthHolds(t *testing.T) {
	for fam, ms := range gather(t, "zip-*") {
		wantMethod := uint16(0)
		if strings.Contains(fam, "deflate") {
			wantMethod = 8
		}
		var pc map[string][]byte
		for i, m := range ms {
			_, content, methods := readZip(t, m.data)
			for n, me := range methods {
				if me != wantMethod {
					t.Fatalf("%s/%s: method %d", fam, n, me)
				}
			}
			if i > 0 {
				for _, n := range m.Truth["unchanged"] {
					if !bytes.Equal(content[n], pc[n]) {
						t.Errorf("%s %s: truth says %s unchanged", fam, m.Revision, n)
					}
				}
				for _, n := range m.Truth["changed"] {
					if bytes.Equal(content[n], pc[n]) {
						t.Errorf("%s %s: truth says %s changed", fam, m.Revision, n)
					}
				}
				for _, n := range m.Truth["added"] {
					if _, ok := pc[n]; ok {
						t.Errorf("%s %s: %s not new", fam, m.Revision, n)
					}
				}
				for _, n := range m.Truth["removed"] {
					if _, ok := content[n]; ok || pc[n] == nil {
						t.Errorf("%s %s: %s not removed", fam, m.Revision, n)
					}
				}
				kind := fam[strings.LastIndex(fam, "-")+1:]
				switch kind {
				case "change":
					if len(m.Truth["changed"]) != 1 || len(m.Truth["added"])+len(m.Truth["removed"]) != 0 {
						t.Errorf("%s %s: truth %v", fam, m.Revision, m.Truth)
					}
				case "add":
					if len(m.Truth["added"]) != 1 || len(m.Truth["changed"]) != 0 {
						t.Errorf("%s %s: truth %v", fam, m.Revision, m.Truth)
					}
				case "remove":
					if len(m.Truth["removed"]) != 1 {
						t.Errorf("%s %s: truth %v", fam, m.Revision, m.Truth)
					}
				case "reorder", "meta":
					if len(m.Truth["changed"])+len(m.Truth["added"])+len(m.Truth["removed"]) != 0 {
						t.Errorf("%s %s: content must be unchanged: %v", fam, m.Revision, m.Truth)
					}
					if bytes.Equal(m.data, ms[i-1].data) {
						t.Errorf("%s %s: bytes identical to parent", fam, m.Revision)
					}
				}
			}
			pc = content
		}
	}
}

func TestTorchZipAligned(t *testing.T) {
	for fam, ms := range gather(t, "torch-*") {
		for _, m := range ms {
			zr, err := zip.NewReader(bytes.NewReader(m.data), int64(len(m.data)))
			if err != nil {
				t.Fatal(err)
			}
			var names []string
			for _, f := range zr.File {
				off, err := f.DataOffset()
				if err != nil || off%64 != 0 || f.Method != 0 {
					t.Errorf("%s %s: offset %d err %v method %d", fam, f.Name, off, err, f.Method)
				}
				names = append(names, f.Name)
			}
			if names[0] != "archive/data.pkl" || names[1] != "archive/byteorder" || names[len(names)-1] != "archive/version" {
				t.Errorf("%s: member order %v", fam, names)
			}
		}
	}
}

func TestGzipFamilies(t *testing.T) {
	for fam, ms := range gather(t, "gzip-*") {
		var prevPlain []byte
		for i, m := range ms {
			zr, err := gzip.NewReader(bytes.NewReader(m.data))
			if err != nil {
				t.Fatal(err)
			}
			plain, err := io.ReadAll(zr)
			if err != nil {
				t.Fatal(err)
			}
			h := sha256.Sum256(plain)
			if hex.EncodeToString(h[:]) != m.Truth["plain_sha256"][0] || strconv.Itoa(len(plain)) != m.Truth["plain_size"][0] {
				t.Errorf("%s %s: truth does not match plaintext", fam, m.Revision)
			}
			if i > 0 && bytes.Equal(plain, prevPlain) {
				t.Errorf("%s %s: mutation changed nothing", fam, m.Revision)
			}
			prevPlain = plain
		}
	}
}

func TestSafetensorsValid(t *testing.T) {
	for fam, ms := range gather(t, "st-*") {
		var prev map[string][]byte
		for i, m := range ms {
			b := m.data
			hl := int(binary.LittleEndian.Uint64(b))
			if hl%8 != 0 || 8+hl > len(b) {
				t.Fatalf("%s: header length %d", fam, hl)
			}
			var hdr map[string]json.RawMessage
			if err := json.Unmarshal(b[8:8+hl], &hdr); err != nil {
				t.Fatalf("%s: %v", fam, err)
			}
			data := b[8+hl:]
			cur := map[string][]byte{}
			covered := 0
			for name, raw := range hdr {
				if name == "__metadata__" {
					continue
				}
				var l struct {
					DType   string `json:"dtype"`
					Shape   []int  `json:"shape"`
					Offsets []int  `json:"data_offsets"`
				}
				json.Unmarshal(raw, &l)
				sz := map[string]int{"BF16": 2, "F16": 2, "F32": 4}[l.DType]
				n := 1
				for _, d := range l.Shape {
					n *= d
				}
				if sz == 0 || l.Offsets[1]-l.Offsets[0] != n*sz || l.Offsets[1] > len(data) {
					t.Fatalf("%s %s: tensor %s inconsistent shape/offsets", fam, m.Revision, name)
				}
				cur[name] = data[l.Offsets[0]:l.Offsets[1]]
				covered += n * sz
			}
			if covered != len(data) {
				t.Fatalf("%s %s: tensors cover %d of %d data bytes", fam, m.Revision, covered, len(data))
			}
			if i > 0 {
				for _, n := range m.Truth["unchanged"] {
					if !bytes.Equal(cur[n], prev[n]) {
						t.Errorf("%s %s: %s claimed unchanged", fam, m.Revision, n)
					}
				}
				for _, n := range m.Truth["changed"] {
					if bytes.Equal(cur[n], prev[n]) {
						t.Errorf("%s %s: %s claimed changed", fam, m.Revision, n)
					}
				}
				if fam == "st-reorder-meta" && (len(m.Truth["unchanged"]) != len(cur) || len(m.data) != len(ms[i-1].data)) {
					t.Errorf("%s: reorder-meta must keep all tensors and total size", fam)
				}
			}
			prev = cur
		}
	}
}

func TestGGUFValid(t *testing.T) {
	for fam, ms := range gather(t, "gguf-*") {
		for _, m := range ms {
			b := m.data
			if string(b[:4]) != "GGUF" || binary.LittleEndian.Uint32(b[4:]) != 3 {
				t.Fatalf("%s: bad magic/version", fam)
			}
			nt, nkv := binary.LittleEndian.Uint64(b[8:]), binary.LittleEndian.Uint64(b[16:])
			p := 24
			str := func() string {
				n := int(binary.LittleEndian.Uint64(b[p:]))
				s := string(b[p+8 : p+8+n])
				p += 8 + n
				return s
			}
			for i := uint64(0); i < nkv; i++ {
				str()
				k := binary.LittleEndian.Uint32(b[p:])
				p += 4
				if k == 8 {
					str()
				} else {
					p += 4
				}
			}
			type ti struct {
				name string
				typ  uint32
				n    uint64
				off  uint64
			}
			var infos []ti
			for i := uint64(0); i < nt; i++ {
				name := str()
				if binary.LittleEndian.Uint32(b[p:]) != 1 {
					t.Fatal("ndims")
				}
				n := binary.LittleEndian.Uint64(b[p+4:])
				typ := binary.LittleEndian.Uint32(b[p+12:])
				off := binary.LittleEndian.Uint64(b[p+16:])
				p += 24
				infos = append(infos, ti{name, typ, n, off})
			}
			data := (p + 31) &^ 31
			for _, in := range infos {
				e, bs := ggufBlock(in.typ)
				sz := int(in.n) / e * bs
				if int(in.off)%32 != 0 || data+int(in.off)+sz > len(b) {
					t.Fatalf("%s %s: tensor %s out of range", fam, m.Revision, in.name)
				}
			}
			if len(b)%32 != 0 {
				t.Errorf("%s: file not padded to alignment", fam)
			}
		}
	}
	ms := gather(t, "gguf-repeated")["gguf-repeated"]
	if len(ms[0].Truth["duplicate_groups"]) == 0 {
		t.Error("gguf-repeated has no duplicate tensor groups")
	}
}

func TestCARValid(t *testing.T) {
	for fam, ms := range gather(t, "car-*") {
		for _, m := range ms {
			b := m.data
			hl, n := binary.Uvarint(b)
			if n <= 0 || !bytes.Contains(b[n:n+int(hl)], []byte("roots")) || b[n+int(hl)-1] != 0x01 {
				t.Fatalf("%s: bad header", fam)
			}
			p := n + int(hl)
			blocks := 0
			for p < len(b) {
				sl, n := binary.Uvarint(b[p:])
				if n <= 0 || p+n+int(sl) > len(b) {
					t.Fatalf("%s: truncated section", fam)
				}
				sec := b[p+n : p+n+int(sl)]
				if sec[0] != 1 || sec[2] != 0x12 || sec[3] != 0x20 {
					t.Fatalf("%s: bad CID", fam)
				}
				h := sha256.Sum256(sec[36:])
				if !bytes.Equal(h[:], sec[4:36]) {
					t.Fatalf("%s: CID does not match block", fam)
				}
				p += n + int(sl)
				blocks++
			}
			if strconv.Itoa(blocks) != m.Truth["blocks_total"][0] {
				t.Errorf("%s: %d blocks, truth %s", fam, blocks, m.Truth["blocks_total"][0])
			}
		}
	}
	// Reorder keeps the block set: every block shared with the parent.
	for _, m := range gather(t, "car-reorder")["car-reorder"][1:] {
		if m.Truth["blocks_shared_with_parent"][0] != m.Truth["blocks_total"][0] {
			t.Errorf("car-reorder %s: not all blocks shared", m.Revision)
		}
	}
	for _, m := range gather(t, "car-overlap")["car-overlap"][1:] {
		s, _ := strconv.Atoi(m.Truth["blocks_shared_with_parent"][0])
		tot, _ := strconv.Atoi(m.Truth["blocks_total"][0])
		if s == 0 || s >= tot {
			t.Errorf("car-overlap %s: shared %d of %d", m.Revision, s, tot)
		}
	}
}

func TestBinaryReferenceShift(t *testing.T) {
	g := gather(t, "bin-*")
	// A pure rebase changes only reference fields; most bytes must be shared.
	ms := g["bin-rebase"]
	a, b := ms[0].data, ms[1].data
	if len(a) != len(b) {
		t.Fatal("rebase changed image size")
	}
	diff := 0
	for i := range a {
		if a[i] != b[i] {
			diff++
		}
	}
	refs, _ := strconv.Atoi(ms[1].Truth["reference_fields"][0])
	if diff == 0 || diff > refs*8+64 {
		t.Errorf("rebase differs in %d bytes with %d reference fields", diff, refs)
	}
	// Meta-only revisions leave everything but the header and build id alone.
	m := g["bin-meta"]
	diff = 0
	for i := range m[0].data {
		if m[0].data[i] != m[1].data[i] {
			diff++
		}
	}
	if diff == 0 || diff > 64 {
		t.Errorf("bin-meta differs in %d bytes", diff)
	}
}

func TestStructuredShapes(t *testing.T) {
	for fam, ms := range gather(t, "pagedb-*") {
		for _, m := range ms {
			if len(m.data)%4096 != 0 || string(m.data[:4]) != "ZPDB" {
				t.Errorf("%s: not page aligned", fam)
			}
		}
	}
	for fam, ms := range gather(t, "colstore-*") {
		for _, m := range ms {
			b := m.data
			if string(b[:4]) != "ZCL1" || string(b[len(b)-4:]) != "ZCL1" {
				t.Errorf("%s: magic", fam)
			}
			fl := int(binary.LittleEndian.Uint32(b[len(b)-8:]))
			foot := b[len(b)-8-fl+0 : len(b)-8]
			n := int(binary.LittleEndian.Uint32(foot))
			if 4+24*n != len(foot) {
				t.Errorf("%s: footer length", fam)
			}
		}
	}
	for fam, ms := range gather(t, "protorec-*") {
		for _, m := range ms {
			p, recs := 0, 0
			for p < len(m.data) {
				l, n := binary.Uvarint(m.data[p:])
				if n <= 0 || p+n+int(l) > len(m.data) {
					t.Fatalf("%s: bad record framing", fam)
				}
				p += n + int(l)
				recs++
			}
			if recs < 4 {
				t.Errorf("%s: %d records", fam, recs)
			}
		}
	}
}

func TestRawControlsRelations(t *testing.T) {
	g := gather(t, "raw-*")
	a := g["raw-append"]
	if !bytes.HasPrefix(a[1].data, a[0].data) {
		t.Error("raw-append must keep the parent as a prefix")
	}
	i := g["raw-insert"]
	if len(i[1].data) != len(i[0].data)+3072 {
		t.Error("raw-insert size")
	}
	d := g["raw-delete"]
	if len(d[1].data) != len(d[0].data)-3072 {
		t.Error("raw-delete size")
	}
	if len(g["raw-sparse-edit"][1].data) != len(g["raw-sparse-edit"][0].data) {
		t.Error("sparse edit changes length")
	}
	if g["raw-random"][1].Truth["relation"][0] != "unrelated" {
		t.Error("random control must be marked unrelated")
	}
}
